public static int calculateTimeNeeded(int N) {
    if (N < 2) {
        throw new IllegalArgumentException("N must be at least 2");
    }

    int timeNeeded = 0;
    int leftIndex = 0;
    int rightIndex = 1;

    while (leftIndex < N && rightIndex < N) {
        timeNeeded++;
        int leftPerson = N - leftIndex - 1;
        int rightPerson = N - rightIndex - 1;

        if (leftPerson != rightPerson) {
            int temp = (leftPerson + rightPerson) % N;
            leftIndex = temp;
            rightIndex = (temp + 1) % N;
        } else {
            leftIndex++;
            rightIndex++;
        }
    }

    return timeNeeded;
}
