    if ((arr.length * (arr.length + 1) / 2) % k != 0) {
        return false;
    }

    // Count the remainders of the array elements when divided by k
    int[] remainderCount = new int[k];

    for (int num : arr) {
        remainderCount[num % k]++;
    }

    // Check if the count of remainders 0, 1, and k-1 are both even or both odd
    if ((remainderCount[0] % 2 == 0 && remainderCount[k / 2] % 2 == 0) ||
        (remainderCount[0] % 2 != 0 && remainderCount[k / 2] % 2 != 0)) {
