public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Step 1: Build the adjacency list representation of the tree
    List<List<Integer>> adjList = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adjList.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adjList.get(edge[0]).add(edge[1]);
        adjList.get(edge[1]).add(edge[0]);
    }

    // Step 2: Recursive helper function to calculate the time to visit each node
    return dfs(0, adjList, hasApple, -1) + 2;
}

private int dfs(int curr, List<List<Integer>> adjList, boolean[] hasApple, int parent) {
    int time = 0;
    for (int next : adjList.get(curr)) {
        if (next != parent) {
            time += dfs(next, adjList, hasApple, curr);
        }
    }
    // Only count the time if the current node has an apple or children with apples
    return time + (hasApple[curr] || time > 0 ? 1 : 0);
}
