public class StringSorter {

    public String sortString(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Input string must not be null or empty");
        }

        Queue<Character> charQueue = new PriorityQueue<>();
        for (char c : s.toCharArray()) {
            charQueue.add(c);
        }

        StringBuilder sb = new StringBuilder();
        while (!charQueue.isEmpty()) {
            for (char c : charQueue) {
                sb.append(c);
                charQueue.remove(c);
            }
            if (charQueue.isEmpty()) {
                break;
            }
            sb.reverse();
            for (char c : charQueue) {
                sb.append(c);
                charQueue.remove(c);
            }
            sb.reverse();
        }

        return sb.toString();
    }

    // Test the method
    public static void main(String[] args) {
        StringSorter sorter = new StringSorter();
        System.out.println(sorter.sortString("bac")); // Output: "abc"
        System.out.println(sorter.sortString("bca")); // Output: "abc"
        System.out.println(sorter.sortString("abba")); // Output: "abbab"
