public static int countDigitOne(int n) {
    int count = 0;
    int power = 1;

    while (n >= power) {
        int digit = (n / power) % 10;
        int digitCount = n / (power * 10);
        if (digit > 1) count += (digitCount + 1) * power;
        else if (digit == 1) count += n % (power * 10) + 1;

        power *= 10;
    }

    return count;
}
