        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                for (int k = 0; k < 4; k++) {
                    int x = i + Directions[k][0];
                    int y = j + Directions[k][1];
                    while (x < m && y < n && mat[x][y] == 1) {
                        length++;
                        x += Directions[k][0];
                        y += Directions[k][1];
                    }
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }

